import type { CreateTaskInput, Priority, TaskFilter, UpdateTaskInput } from './store'

export const MAX_TITLE_LENGTH = 120

export const PRIORITIES = ['low', 'normal', 'high'] as const

export type ErrorBody = {
  error: { code: string; message: string; details?: string[] }
}

export type Parsed<T> = { ok: true; value: T } | { ok: false; error: ErrorBody }

export function badRequest(message: string, details?: string[]): ErrorBody {
  return { error: { code: 'bad_request', message, ...(details ? { details } : {}) } }
}

export function notFound(id: string): ErrorBody {
  return { error: { code: 'not_found', message: `Task '${id}' not found` } }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Reads the request body as JSON, or `undefined` when it isn't valid JSON. */
export async function readJson(c: { req: { json(): Promise<unknown> } }): Promise<unknown | undefined> {
  try {
    return await c.req.json()
  } catch {
    return undefined
  }
}

/** Validates a `title` value, returning the normalised title or an error message. */
function parseTitle(value: unknown): { ok: true; value: string } | { ok: false; error: string } {
  if (typeof value !== 'string') return { ok: false, error: '"title" must be a string' }
  const title = value.trim()
  if (title.length === 0) return { ok: false, error: '"title" must not be empty' }
  if (title.length > MAX_TITLE_LENGTH) {
    return { ok: false, error: `"title" must be at most ${MAX_TITLE_LENGTH} characters` }
  }
  return { ok: true, value: title }
}

function isPriority(value: unknown): value is Priority {
  return typeof value === 'string' && (PRIORITIES as readonly string[]).includes(value)
}

const PRIORITY_ERROR = `"priority" must be one of ${PRIORITIES.map((p) => `"${p}"`).join(', ')}`

/** Validates a `priority` value, returning it or an error message. */
function parsePriority(value: unknown): { ok: true; value: Priority } | { ok: false; error: string } {
  if (!isPriority(value)) return { ok: false, error: PRIORITY_ERROR }
  return { ok: true, value }
}

/** `done` was renamed to `completed`, so a body still carrying it is invalid. */
function rejectRenamedField(body: Record<string, unknown>): string | undefined {
  if ('done' in body) return '"done" is not a task field; use "completed"'
  return undefined
}

/** Validates the body of `POST /tasks`. */
export function parseCreateTask(body: unknown): Parsed<CreateTaskInput> {
  if (!isPlainObject(body)) {
    return { ok: false, error: badRequest('Request body must be a JSON object') }
  }

  const details: string[] = []

  const renamed = rejectRenamedField(body)
  if (renamed) details.push(renamed)

  let title: string | undefined
  const parsedTitle = parseTitle(body.title)
  if (parsedTitle.ok) title = parsedTitle.value
  else details.push(parsedTitle.error)

  let completed: boolean | undefined
  if (body.completed !== undefined) {
    if (typeof body.completed === 'boolean') completed = body.completed
    else details.push('"completed" must be a boolean')
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsedPriority = parsePriority(body.priority)
    if (parsedPriority.ok) priority = parsedPriority.value
    else details.push(parsedPriority.error)
  }

  if (details.length > 0) {
    return { ok: false, error: badRequest('Invalid task payload', details) }
  }

  return { ok: true, value: { title: title as string, completed, priority } }
}

/** Validates the body of `PATCH /tasks/:id`. */
export function parseUpdateTask(body: unknown): Parsed<UpdateTaskInput> {
  if (!isPlainObject(body)) {
    return { ok: false, error: badRequest('Request body must be a JSON object') }
  }

  const details: string[] = []

  const renamed = rejectRenamedField(body)
  if (renamed) details.push(renamed)

  let title: string | undefined
  if (body.title !== undefined) {
    const parsedTitle = parseTitle(body.title)
    if (parsedTitle.ok) title = parsedTitle.value
    else details.push(parsedTitle.error)
  }

  let completed: boolean | undefined
  if (body.completed !== undefined) {
    if (typeof body.completed === 'boolean') completed = body.completed
    else details.push('"completed" must be a boolean')
  }

  let priority: Priority | undefined
  if (body.priority !== undefined) {
    const parsedPriority = parsePriority(body.priority)
    if (parsedPriority.ok) priority = parsedPriority.value
    else details.push(parsedPriority.error)
  }

  if (body.title === undefined && body.completed === undefined && body.priority === undefined) {
    details.push('At least one of "title", "completed" or "priority" must be provided')
  }

  if (details.length > 0) {
    return { ok: false, error: badRequest('Invalid task payload', details) }
  }

  return { ok: true, value: { title, completed, priority } }
}

/** Validates the query string of `GET /tasks` into a storage filter. */
export function parseTaskFilter(query: Record<string, string | undefined>): Parsed<TaskFilter> {
  const details: string[] = []

  let completed: boolean | undefined
  if (query.completed !== undefined) {
    if (query.completed === 'true') completed = true
    else if (query.completed === 'false') completed = false
    else details.push('"completed" must be "true" or "false"')
  }

  let priority: Priority | undefined
  if (query.priority !== undefined) {
    const parsedPriority = parsePriority(query.priority)
    if (parsedPriority.ok) priority = parsedPriority.value
    else details.push(parsedPriority.error)
  }

  if (details.length > 0) {
    return { ok: false, error: badRequest('Invalid query parameters', details) }
  }

  return { ok: true, value: { completed, priority } }
}

export type Priority = 'low' | 'normal' | 'high'

export type Task = {
  id: string
  title: string
  completed: boolean
  priority: Priority
  createdAt: string
  updatedAt: string
}

export type CreateTaskInput = {
  title: string
  completed?: boolean
  priority?: Priority
}

export type UpdateTaskInput = {
  title?: string
  completed?: boolean
  priority?: Priority
}

/** Filter applied by `TaskStore#list`. An absent field matches every task. */
export type TaskFilter = {
  completed?: boolean
  priority?: Priority
}

/**
 * In-memory task storage. A class (rather than module-level state) so that
 * every app instance — in particular every test — starts from a clean slate.
 */
export class TaskStore {
  #tasks = new Map<string, Task>()
  #nextId = 1

  list(filter: TaskFilter): Task[] {
    return [...this.#tasks.values()].filter((task) => {
      if (filter.completed !== undefined && task.completed !== filter.completed) return false
      if (filter.priority !== undefined && task.priority !== filter.priority) return false
      return true
    })
  }

  get(id: string): Task | undefined {
    return this.#tasks.get(id)
  }

  create(input: CreateTaskInput): Task {
    const now = new Date().toISOString()
    const task: Task = {
      id: String(this.#nextId++),
      title: input.title,
      completed: input.completed ?? false,
      priority: input.priority ?? 'normal',
      createdAt: now,
      updatedAt: now,
    }
    this.#tasks.set(task.id, task)
    return task
  }

  update(id: string, input: UpdateTaskInput): Task | undefined {
    const task = this.#tasks.get(id)
    if (!task) return undefined

    const updated: Task = {
      ...task,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.completed !== undefined ? { completed: input.completed } : {}),
      ...(input.priority !== undefined ? { priority: input.priority } : {}),
      updatedAt: new Date().toISOString(),
    }
    this.#tasks.set(id, updated)
    return updated
  }

  delete(id: string): Task | undefined {
    const task = this.#tasks.get(id)
    if (!task) return undefined
    this.#tasks.delete(id)
    return task
  }
}

import { Hono } from 'hono'
import { TaskStore, type Task } from './store'
import {
  notFound,
  parseCreateTask,
  parseTaskFilter,
  parseUpdateTask,
  readJson,
} from './validation'

type Variables = {
  store: TaskStore
}

export function createApp(store: TaskStore = new TaskStore()) {
  const app = new Hono<{ Variables: Variables }>()

  app.get('/', (c) => {
    return c.text('Hello Hono!')
  })

  app.post('/tasks', async (c) => {
    const parsed = parseCreateTask(await readJson(c))
    if (!parsed.ok) return c.json(parsed.error, 400)

    const task: Task = store.create(parsed.value)
    return c.json(task, 201)
  })

  app.get('/tasks', (c) => {
    const parsed = parseTaskFilter(c.req.query())
    if (!parsed.ok) return c.json(parsed.error, 400)

    return c.json(store.list(parsed.value))
  })

  app.get('/tasks/:id', (c) => {
    const id = c.req.param('id')
    const task = store.get(id)
    if (!task) return c.json(notFound(id), 404)
    return c.json(task)
  })

  app.patch('/tasks/:id', async (c) => {
    const id = c.req.param('id')

    const parsed = parseUpdateTask(await readJson(c))
    if (!parsed.ok) return c.json(parsed.error, 400)

    // Validation passed, so a missing task is the only remaining failure mode.
    const updated = store.update(id, parsed.value)
    if (!updated) return c.json(notFound(id), 404)
    return c.json(updated)
  })

  app.delete('/tasks/:id', (c) => {
    const id = c.req.param('id')
    const deleted = store.delete(id)
    if (!deleted) return c.json(notFound(id), 404)
    return c.body(null, 204)
  })

  return app
}

