  describe('filtering', () => {
    async function seed() {
      await postJson('/tasks', { title: 'done high', completed: true, priority: 'high' })
      await postJson('/tasks', { title: 'open high', completed: false, priority: 'high' })
      await postJson('/tasks', { title: 'done low', completed: true, priority: 'low' })
      await postJson('/tasks', { title: 'open normal' })
    }

    async function titles(path: string): Promise<string[]> {
      const res = await request(path)
      expect(res.status).toBe(200)
      return ((await res.json()) as Task[]).map((t) => t.title)
    }

    it('filters by completed=true', async () => {
      await seed()
      expect(await titles('/tasks?completed=true')).toEqual(['done high', 'done low'])
    })

    it('filters by completed=false', async () => {
      await seed()
      expect(await titles('/tasks?completed=false')).toEqual(['open high', 'open normal'])
    })

    it('filters by priority', async () => {
      await seed()
      expect(await titles('/tasks?priority=high')).toEqual(['done high', 'open high'])
      expect(await titles('/tasks?priority=low')).toEqual(['done low'])
      expect(await titles('/tasks?priority=normal')).toEqual(['open normal'])
    })

    it('combines both filters', async () => {
      await seed()
      expect(await titles('/tasks?completed=true&priority=high')).toEqual(['done high'])
      expect(await titles('/tasks?completed=false&priority=low')).toEqual([])
    })

    it('returns every task when no filter is given', async () => {
      await seed()
      expect(await titles('/tasks')).toHaveLength(4)
    })

    it('rejects a non-boolean completed filter with 400', async () => {
      const res = await request('/tasks?completed=yes')
      expect(res.status).toBe(400)

      const body = (await res.json()) as { error: { code: string; message: string } }
      expect(body.error.code).toBe('bad_request')
      expect(typeof body.error.message).toBe('string')
    })

    it('rejects an unknown priority filter with 400', async () => {
      const res = await request('/tasks?priority=urgent')
      expect(res.status).toBe(400)
      expect((await res.json()) as { error: unknown }).toHaveProperty('error')
    })
  })
})

