it('updates the completed flag only', async () => {
  const created = await createTask('toggle me')

  const res = await patchJson(`/tasks/${created.id}`, { completed: true })
  expect(res.status).toBe(200)

  const updated = (await res.json()) as Task
  expect(updated.completed).toBe(true)
  expect(updated.title).toBe(created.title)
})

it('updates the priority only', async () => {
  const created = await createTask('reprioritise me')

  const res = await patchJson(`/tasks/${created.id}`, { priority: 'low' })
  expect(res.status).toBe(200)

  const updated = (await res.json()) as Task
  expect(updated.priority).toBe('low')
  expect(updated.title).toBe(created.title)
  expect(updated.completed).toBe(created.completed)
})

it('updates every field at once', async () => {
  const created = await createTask('both')

  const res = await patchJson(`/tasks/${created.id}`, {
    title: 'renamed',
    completed: true,
    priority: 'high',
  })
  expect(res.status).toBe(200)
  expect((await res.json()) as Task).toMatchObject({
    title: 'renamed',
    completed: true,
    priority: 'high',
  })
})

